import math
from functools import reduce

def gcd(a, b):
    while b:
        a, b = b, a % b
    return a

def lcm(a, b):
    if a == 0 or b == 0:
        return 0
    return abs(a * b) // gcd(a, b)

def lcm_range(start, end):
    if start > end:
        return 1
    return reduce(lcm, range(start, end + 1))

N = 3
K_max = 20

x_values = []
ratios = []

print(f"--- Calculating x_k = LCM(k, k+1, k+2) for k=1 to {K_max} ---")
for k in range(1, K_max + 1):
    # x_k = lcm(k, k+1, ..., k+n-1)
    x_k = lcm_range(k, k + N - 1)
    x_values.append(x_k)

    if k < K_max:
        x_k_plus_1 = lcm_range(k + 1, k + N)
        ratio = x_k_plus_1 / x_k
        ratios.append(ratio)
    else:
        ratios.append(None)

# Print results for k=1 to K_max
print("\n--- x_k Values (k=1 to 20) ---")
for k, x_k in enumerate(x_values):
    print(f"x_{k+1} = {x_k}")

# Print ratios for k=1 to K_max-1 (ratio = x_{k+1} / x_k)
print("\n--- Ratios x_{k+1} / x_k (k=1 to 19) ---")
for k in range(K_max - 1):
    ratio = ratios[k]
    print(f"x_{k+2} / x_{k+1} (for k={k+1}) = {ratio}")

# Check for strict increase for k > N (N=3 for this specific check)
# We check k=4 onwards. (k=1 corresponds to x_2/x_1, k=3 corresponds to x_4/x_3)
print("\n--- Analysis for k > 3 ---")
is_strictly_increasing = True
for k_index in range(3, K_max - 1): # k=4 corresponds to k_index=3 (since k starts at 1 for ratio index)
    ratio = ratios[k_index]
    if ratio <= 1.0 + 1e-9: # Allow for minor float errors
        is_strictly_increasing = False
        print(f"Ratio x_{k_index+2} / x_{k_index+1} <= 1 found at k={k_index+1}: {ratio}")
        break

if is_strictly_increasing:
    print("x_k appears strictly increasing for k > 3 (up to k=20).")
else:
    print("x_k is NOT strictly increasing for k > 3 (up to k=20).")

